import "slick-carousel/slick/slick.css";
import "slick-carousel/slick/slick-theme.css";
import "./EventsSlider.css"; // Özel CSS dosyanız
import React from "react";
import Slider from "react-slick";

const SliderComponent = () => {
  const settings = {
    dots: true,
    infinite: true,
    speed: 500,
    slidesToShow: 1,
    slidesToScroll: 1,
  };

  return (
    <div className="slider-container">
      <div className="frame-container">
        <div className="frame-header">
          <div className="shape-dots-1"></div>
          <div className="kesik-yan-cizgi-1">
            <div className="vector"></div>
          </div>
        </div>

        <Slider {...settings}>
          <div className="frame-main">
            <div className="frame-slider"></div>
          </div>
          <div className="frame-main-alt">
            <h3 className="slide-text">Slide 2</h3>
          </div>
        </Slider>
      </div>
      <div className="frame-footer"></div>
    </div>
  );
};

export default SliderComponent;
